<?php declare(strict_types=1); ?>
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111b35"><title>HEX CHEATS SHOP | Homepage control</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;color:#16233b;background:#f3f6fb;--navy:#111b35;--blue:#3478f6;--line:#dce4ef;--muted:#71809a;--green:#18865d;--red:#bd3b4b}*{box-sizing:border-box}body{margin:0}.top{min-height:68px;background:var(--navy);color:white;display:flex;align-items:center;justify-content:space-between;padding:12px max(16px,calc((100% - 1180px)/2));gap:12px}.brand{font-weight:900;letter-spacing:.04em;color:white;text-decoration:none}.actions{display:flex;gap:8px;flex-wrap:wrap}.wrap{width:min(1180px,calc(100% - 30px));margin:25px auto 55px}.button{border:1px solid transparent;border-radius:9px;padding:9px 13px;background:var(--blue);color:white;font-size:12px;font-weight:750;cursor:pointer;text-decoration:none}.button.secondary{background:white;border-color:var(--line);color:#34445e}.button.danger{background:#fff;border-color:#f0ccd0;color:var(--red)}.button:disabled{opacity:.55;cursor:wait}.heading{display:flex;justify-content:space-between;align-items:end;gap:12px;margin-bottom:16px}.heading h1{margin:4px 0;font-size:27px;letter-spacing:-.04em}.muted{color:var(--muted);font-size:12px}.note{background:#edf4ff;border:1px solid #d6e5ff;color:#315184;border-radius:10px;padding:12px 14px;font-size:11px;line-height:1.6;margin-bottom:17px}.panel,.banner{background:white;border:1px solid var(--line);border-radius:14px;padding:17px;margin:0 0 14px;box-shadow:0 5px 22px #16345e08}.panel h2,.banner h2{font-size:15px;margin:0 0 13px}.form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field.full{grid-column:1/-1}.field label{display:block;font-size:10px;font-weight:800;color:#556780;margin:0 0 6px}.field input,.field textarea{width:100%;border:1px solid #d4deea;border-radius:8px;padding:10px;font:12px inherit;color:#1a2942}.field textarea{min-height:78px;resize:vertical;line-height:1.5}.save-row{display:flex;justify-content:flex-end;gap:8px;margin-top:13px}.banner-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.preview{height:135px;border-radius:10px;background:linear-gradient(130deg,#0d1d44,#1c4ca5 52%,#31297f);display:grid;place-items:center;color:#cfe0ff;font-size:12px;font-weight:800;overflow:hidden;margin-bottom:12px}.preview img{width:100%;height:100%;object-fit:cover}.small{font-size:10px;color:var(--muted);margin-top:5px}.status{min-height:18px;color:var(--green);font-size:11px;margin-top:10px}.status.error{color:var(--red)}@media(max-width:760px){.banner-grid{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}.form{grid-template-columns:1fr}.field.full{grid-column:auto}.heading{align-items:flex-start;flex-direction:column}}
</style></head><body>
<header class="top"><a class="brand" href="/admin/catalog">HEX CHEATS SHOP · HOMEPAGE</a><nav class="actions"><a class="button secondary" href="/admin/catalog">Catalog</a><a class="button secondary" href="/admin/customers">Customers &amp; orders</a><a class="button secondary" href="/">View shop</a><button class="button secondary" id="logout">Sign out</button></nav></header>
<main class="wrap"><div class="heading"><div><div class="muted">Storefront appearance</div><h1>Homepage &amp; banners</h1><div class="muted">Shop settings and all three banner images are saved in the shared SQLite database.</div></div></div>
<div class="note">Upload landscape PNG, JPEG, or WebP images (up to 8 MB each). Banner buttons may point to <code>#catalog</code> or an HTTPS URL. Never place API keys or private customer information in banner text.</div>
<form id="settingsForm" class="panel"><h2>Store text</h2><div class="form"><div class="field"><label for="shop_name">Shop name</label><input id="shop_name" maxlength="80" required></div><div class="field"><label for="announcement">Announcement strip</label><input id="announcement" maxlength="300" required></div><div class="field"><label for="hero_title">Hero headline</label><input id="hero_title" maxlength="120" required></div><div class="field"><label for="hero_subtitle">Hero supporting text</label><textarea id="hero_subtitle" maxlength="360" required></textarea></div></div><div class="save-row"><button class="button" id="saveSettings">Save shop text</button></div><div class="status" id="settingsStatus"></div></form>
<form id="passwordForm" class="panel"><h2>Change administrator password</h2><div class="note">Password changes are hashed in the database. After saving, all admin sessions are signed out and you must sign in again.</div><div class="form"><div class="field"><label for="adminEmail">Admin email</label><input id="adminEmail" type="email" maxlength="254" required autocomplete="username"></div><div class="field"><label for="currentPassword">Current password</label><input id="currentPassword" type="password" maxlength="256" required autocomplete="current-password"></div><div class="field"><label for="newPassword">New password (12 characters minimum)</label><input id="newPassword" type="password" minlength="12" maxlength="256" required autocomplete="new-password"></div></div><div class="save-row"><button class="button secondary" id="savePassword">Change password</button></div><div class="status" id="passwordStatus"></div></form>
<section class="panel"><h2>Binance Pay · USD wallet top-ups</h2><div class="note">Customers pay the exact USD amount, upload a screenshot and transaction ID, and an admin verifies the transfer in Binance before crediting the INR wallet. The QR image and instructions are stored in the same SQLite database.</div><form id="binanceSettingsForm"><div class="field"><label for="binanceInstructionsInput">Customer instructions</label><textarea id="binanceInstructionsInput" maxlength="800" required></textarea></div><div class="save-row"><button class="button secondary" type="submit">Save instructions</button></div></form><div class="preview" id="binanceQrPreview">No Binance QR uploaded</div><div class="field"><label for="binanceQrFile">Binance Pay QR image (PNG, JPEG, WebP · max 6 MB)</label><input id="binanceQrFile" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="save-row"><button class="button" id="uploadBinanceQr" type="button">Upload QR</button><button class="button danger" id="removeBinanceQr" type="button" disabled>Remove QR</button></div><div class="status" id="binanceStatus"></div></section>
<section class="banner-grid" id="bannerGrid"><div class="banner">Loading banner settings…</div></section><div class="status" id="pageStatus"></div></main>
<script>
const $=id=>document.getElementById(id);let token=localStorage.getItem('hex_admin_token')||'';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const headers={...(options.headers||{}),'X-Admin-Token':token};const r=await fetch(path,{...options,headers,credentials:'same-origin'});let d={};try{d=await r.json()}catch{}if(r.status===401){localStorage.removeItem('hex_admin_token');location.href='/admin';throw Error('Admin sign-in required.')}if(!r.ok)throw Error(d.error||'Request failed.');return d}
function renderBanners(items){$('bannerGrid').innerHTML=(items||[]).map(b=>`<form class="banner" data-slot="${Number(b.slot)}"><h2>Banner slot ${Number(b.slot)}</h2><div class="preview">${b.image_url?`<img src="${esc(b.image_url)}" alt="Banner ${Number(b.slot)}">`:'Upload a banner image'}</div><div class="field"><label>Banner title</label><input name="title" maxlength="120" value="${esc(b.title)}"></div><div class="field"><label>Supporting text</label><textarea name="subtitle" maxlength="240">${esc(b.subtitle)}</textarea></div><div class="field"><label>Button label</label><input name="cta_label" maxlength="32" value="${esc(b.cta_label||'Browse products')}"></div><div class="field"><label>Button URL (#catalog or HTTPS)</label><input name="cta_url" maxlength="2048" value="${esc(b.cta_url||'#catalog')}"></div><div class="field"><label>Banner image (PNG/JPEG/WebP · max 8 MB)</label><input name="image" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="save-row"><button class="button secondary" type="button" data-remove="${Number(b.slot)}" ${b.image_url?'':'disabled'}>Remove image</button><button class="button" type="submit">Save banner</button></div><div class="status"></div></form>`).join('');}
function renderBinance(b={}){$('binanceInstructionsInput').value=b.instructions||'';$('binanceQrPreview').innerHTML=b.available?`<img src="/api/store/payments/binance/qr?v=${Number(b.updated_at||0)}" alt="Binance Pay QR" style="width:100%;height:100%;object-fit:contain;background:#fff;padding:8px">`:'No Binance QR uploaded';$('removeBinanceQr').disabled=!b.available}
async function load(){try{const d=await api('/admin/api/homepage');const h=d.homepage||{};for(const k of ['shop_name','announcement','hero_title','hero_subtitle'])$(k).value=h[k]||'';renderBanners(h.banners);renderBinance(h.binance)}catch(e){$('bannerGrid').innerHTML=`<div class="banner">${esc(e.message)}</div>`}}
$('settingsForm').addEventListener('submit',async e=>{e.preventDefault();const b=$('saveSettings');b.disabled=true;$('settingsStatus').textContent='';try{await api('/admin/api/homepage',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(['shop_name','announcement','hero_title','hero_subtitle'].map(k=>[k,$(k).value.trim()]))) });$('settingsStatus').textContent='Shop text saved.'}catch(err){$('settingsStatus').textContent=err.message;$('settingsStatus').className='status error'}finally{b.disabled=false}});
$('passwordForm').addEventListener('submit',async e=>{e.preventDefault();const b=$('savePassword');b.disabled=true;$('passwordStatus').textContent='';try{await api('/admin/api/admin/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('adminEmail').value.trim(),current_password:$('currentPassword').value,new_password:$('newPassword').value})});localStorage.removeItem('hex_admin_token');$('passwordStatus').textContent='Password changed. Redirecting to sign in…';setTimeout(()=>location.href='/admin',900)}catch(err){$('passwordStatus').textContent=err.message;$('passwordStatus').className='status error'}finally{b.disabled=false}});
$('bannerGrid').addEventListener('submit',async e=>{const form=e.target.closest('form[data-slot]');if(!form)return;e.preventDefault();const slot=Number(form.dataset.slot),status=form.querySelector('.status'),button=form.querySelector('button[type=submit]');button.disabled=true;status.textContent='';try{const payload=Object.fromEntries(['title','subtitle','cta_label','cta_url'].map(k=>[k,form.elements[k].value.trim()]));await api(`/admin/api/banners/${slot}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const file=form.elements.image.files?.[0];if(file){if(file.size>8*1024*1024)throw Error('Image must be 8 MB or smaller.');const fd=new FormData();fd.append('image',file,file.name);await api(`/admin/api/banners/${slot}/image`,{method:'POST',body:fd})}status.textContent='Banner saved.';await load()}catch(err){status.textContent=err.message;status.className='status error'}finally{button.disabled=false}});
$('bannerGrid').addEventListener('click',async e=>{const b=e.target.closest('[data-remove]');if(!b)return;const slot=Number(b.dataset.remove);if(!confirm(`Remove the image from banner ${slot}?`))return;b.disabled=true;try{await api(`/admin/api/banners/${slot}/image`,{method:'DELETE'});await load()}catch(err){$('pageStatus').textContent=err.message;$('pageStatus').className='status error'}finally{b.disabled=false}});
$('binanceSettingsForm').addEventListener('submit',async e=>{e.preventDefault();$('binanceStatus').textContent='';try{await api('/admin/api/payments/binance',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({instructions:$('binanceInstructionsInput').value.trim()})});$('binanceStatus').textContent='Binance instructions saved.'}catch(err){$('binanceStatus').textContent=err.message;$('binanceStatus').className='status error'}});
$('uploadBinanceQr').addEventListener('click',async e=>{const button=e.currentTarget,file=$('binanceQrFile').files?.[0];if(!file){$('binanceStatus').textContent='Choose the Binance QR image first.';$('binanceStatus').className='status error';return}if(file.size>6*1024*1024){$('binanceStatus').textContent='QR image must be 6 MB or smaller.';$('binanceStatus').className='status error';return}button.disabled=true;$('binanceStatus').textContent='';try{const form=new FormData();form.append('image',file,file.name);await api('/admin/api/payments/binance/qr',{method:'POST',body:form});$('binanceQrFile').value='';$('binanceStatus').textContent='Binance QR saved in the shared database.';await load()}catch(err){$('binanceStatus').textContent=err.message;$('binanceStatus').className='status error'}finally{button.disabled=false}});
$('removeBinanceQr').addEventListener('click',async e=>{if(!confirm('Remove the Binance Pay QR? Customers will no longer be able to create Binance top-ups.'))return;e.currentTarget.disabled=true;try{await api('/admin/api/payments/binance/qr',{method:'DELETE'});$('binanceStatus').textContent='Binance QR removed.';await load()}catch(err){$('binanceStatus').textContent=err.message;$('binanceStatus').className='status error'}finally{e.currentTarget.disabled=false}});
$('logout').addEventListener('click',()=>{localStorage.removeItem('hex_admin_token');location.href='/admin'});if(!token)location.href='/admin';else load();
</script></body></html>
